mapper.select:
SELECT h.fact_id FROM agent_runtime_memory_fact_heads h
JOIN agent_runtime_memory_fact_revisions r ON r.tenant_id=h.tenant_id AND r.fact_id=h.fact_id AND r.revision=h.current_revision
WHERE h.tenant_id=#{tenant} AND h.group_binding_id=#{group}
  AND (h.scope='GROUP' OR h.scope='GROUP_MEMBER' AND h.subject_end_user_id=#{subject})
AND h.scope=#{scope}
AND r.status=#{status}
ORDER BY r.created_epoch_second DESC,r.created_nano DESC,h.fact_id LIMIT #{limit}
